48	/* Elements per family — a RUNTIME knob, not a compile-time constant:
49	 * "-O sleef_neon.nelems=N". The default reproduces the historical
50	 * ELEMS=1024 exactly (identical RNG consumption order, byte-identical
51	 * inputs/goldens). Footprint tiers on Kunpeng 920 (TSV110 core):
52	 *   1024   — a double replay segment touches input+golden+scratch
53	 *            3 x 8KB = 24KB, resident in L1D (64KB)
54	 *   16384  — 3 x 128KB = 384KB per double segment -> L2 (512KB)
55	 *   262144 — 2MB per double buffer (1MB float) x several buffers
56	 *            -> LLC / DRAM
57	 * (different cache structures hold different ACE residency; the
58	 * openblas mdim knob is the same lesson's GEMM version). ELEMS_MIN and
59	 * every accepted value must be a multiple of 4: the float halves advance
60	 * in float32x4_t stride-4 steps (double stride 2 divides 4), and a
61	 * non-multiple would make the last vector iteration overrun its buffer
62	 * (validated loudly in init). Per-thread scratch ceiling at ELEMS_MAX:
63	 * od (2MB double) + of (1MB float) = 3MB per worker, inputs/goldens are
64	 * shared, 192-core worst case ~ 192 x 3MB = 576MB scratch — acceptable. */
65	#define ELEMS_DEFAULT 1024  /* elements per family: 512 float64x2 vectors (double half) + 256 float32x4 vectors (float half) */
66	#define ELEMS_MIN 128       /* multiple of 4 — float32x4_t stride (see above) */
67	#define ELEMS_MAX 262144    /* per-thread scratch ceiling ~3MB/worker (see above) */
68	
69	namespace {
70	struct sleef_test_data {
71	    /* elements per family, from the -O sleef_neon.nelems=N knob
72	     * (ELEMS_MIN..ELEMS_MAX, default ELEMS_DEFAULT): every loop bound and
73	     * buffer size below derives from it, so the whole working set (inputs
74	     * + goldens + per-thread scratch) scales with the knob — see the
75	     * ELEMS_DEFAULT comment above for the L1/L2/LLC/DRAM tier rationale */
76	    int nelems;
77	    /* per-domain inputs (each family keeps its own array so the run loop
78	     * can replay exactly the inputs the golden values were computed from) */
79	    double *xd_trig, *xd_exp, *xd_log;
80	    float  *xf_trig, *xf_exp, *xf_log;
81	    /* golden outputs (read-only after init) */
82	    double *gd_sin, *gd_cos, *gd_exp, *gd_log;
83	    float  *gf_sin, *gf_cos, *gf_exp, *gf_log;
84	    /* u35 second-accuracy tier golden outputs (SLEEF's other polynomial
85	     * implementation of the same math; u35 NEON has no exp — exp2 stands
86	     * in, itself an independent FMA chain) */
87	    double *gd_sin35, *gd_cos35, *gd_log35, *gd_exp2_35;
88	    float  *gf_sin35, *gf_cos35, *gf_log35, *gf_exp2_35;
89	    /* new function families: inputs, then golden outputs. asin/atan share
90	     * the [-1,1) input array (xd_inv/xf_inv); cbrt/log10/sinh/tanh reuse
91	     * the cbrt/log/exp domain arrays respectively (cbrt gets its own wide
92	     * [-1000,1000) array; log10 reuses xd_log/xf_log, sinh/tanh reuse
93	     * xd_exp/xf_exp). pow is the only two-argument kernel: xd_pow2/xf_pow2
94	     * hold the bases, xd_pexp/xf_pexp the exponents. */
95	    double *xd_inv,  *xd_cbrt, *gd_asin, *gd_atan, *gd_cbrt, *gd_log10, *gd_sinh, *gd_tanh;
96	    double *xd_pow2, *xd_pexp, *gd_pow;
97	    float  *xf_inv,  *xf_cbrt, *gf_asin, *gf_atan, *gf_cbrt, *gf_log10, *gf_sinh, *gf_tanh;
98	    float  *xf_pow2, *xf_pexp, *gf_pow;
99	};
100	}
