104	/* Scratch output buffers are per-thread: the framework runs one worker
105	 * thread per core and they all share test->data, so anything written during
106	 * test_run must be thread-local (od/of are the kernel destinations, written
107	 * every iteration). Allocated lazily on first use and intentionally not
108	 * freed in cleanup, exactly like the openblas_* scratch buffers: the worker
109	 * threads are gone (or never existed) when the main thread runs
110	 * test_cleanup, and the forked child exits right after, so the OS reclaims
111	 * the storage. calloc zeroes them once so a short first iteration can never
112	 * compare garbage. */
113	static thread_local double *od = nullptr;
114	static thread_local float  *of = nullptr;
115	
116	/* Uniform double in [0,1) from the framework RNG (top 53 bits; libc rand is
117	 * trapped by the framework). */
118	static double uniform01(void)
119	{
120	    return (double)(random64() >> 11) / 9007199254740992.0;
121	}
