123	/* Domain-boundary analysis for the mappings below (the naive u*span+lo
124	 * write-up can round to the boundary itself):
125	 *  - trig : u in [0,1) tops out at 1-2^-53, so u*2-1 (exact in binary)
126	 *           lies in [-1, 1-2^-52]; times pi the magnitude stays
127	 *           <= pi*(1-2^-52)*(1+2eps) — strictly inside [-pi, pi] after the
128	 *           two roundings. sin/cos of that is also guaranteed finite and
129	 *           well inside [-1, 1].
130	 *  - exp  : same construction over [-20, 20-2^-48]; exp of that is in
131	 *           [~2e-9, ~4.85e8], forty orders from overflow and far above
132	 *           subnormal double/float (float min normal ~1.2e-38).
133	 *  - log  : u in [0,1) plus 1e-300 keeps the argument strictly positive
134	 *           (u==0 gives 1e-300, a normal double; the float variant uses
135	 *           1e-30 so the offset survives the float narrowing), scaled by
136	 *           1e10: log arguments span [1e-290, 1e10) for the double variant
137	 *           ([~1e-20, ~1e10) once narrowed to float), all finite, all
138	 *           inside SLEEF's u10 accuracy domain (positive reals).
139	 *
140	 * Domain-boundary analysis for the u35 tier and the new families:
141	 *  - u35 tier: identical input arrays and identical domain analysis as the
142	 *    u10 tier above (trig for sin/cos, log for log, exp for exp2 — exp2's
143	 *    domain is all reals and exp2 of [-20,20) is [2^-20, 2^20) = [~9.5e-7,
144	 *    ~1.05e6], comfortably finite in both widths). The u35 kernels are a
145	 *    DIFFERENT polynomial implementation of the same functions, so the
146	 *    outputs land on different bits than u10 — that is the point (second
147	 *    phase sample), and determinism is per-kernel so the byte-exact golden
148	 *    compare stays valid.
149	 *  - asin/atan: input u*2-1 in [-1, 1-2^-52] (exact in binary, same
150	 *    construction as trig without the pi scaling). asin's domain [-1,1]
151	 *    includes the endpoint -1 (u==0 gives exactly -1, asin(-1) = -pi/2,
152	 *    finite); atan is defined on all reals so [-1,1) is trivially safe.
153	 *    Output ranges: asin in [-pi/2, pi/2], atan in (-pi/2, pi/2) — the
154	 *    init sentinel uses the generous bound 1.6 (> pi/2 ~ 1.5708).
155	 *  - cbrt: input u*2000-1000 in [-1000, 1000-2^-43]. cbrt is defined on
156	 *    all reals (odd function, exact at 0, negative inputs give negative
157	 *    outputs); cbrt of that range is within [-10, 10) (cbrt(1000) = 10
158	 *    not included since the top is 1000-eps). Exercises the three states
159	 *    negative / zero / positive-plus-large in one family.
160	 *  - log10: reuses the log positive mapping, i.e. arguments in
161	 *    [1e-290, 1e10) double / [~1e-20, ~1e10) float. log10 of that is in
162	 *    (-290, 10] double / (-20, 10] float — the init sentinel uses
163	 *    (-700, 25] / (-30, 25] with generous headroom on both sides.
164	 *  - sinh/tanh: reuse the exp mapping [-20, 20). sinh(20) ~ 2.42e8 and
165	 *    sinh(-20) ~ -2.42e8 — far from double overflow (1.8e308) and float
166	 *    overflow (3.4e38); the init sentinel bound is 1e9. tanh of [-20,20)
167	 *    is in (-1, 1) mathematically, BUT SLEEF's tanh kernels (both u10
168	 *    xtanh and u35 xtanh_u35, verified in sleefsimddp.c) clamp to +-1.0
169	 *    for |x| > 18.714973875, and inputs in (18.715, 20) DO produce
170	 *    exactly +-1.0 by design. The sentinel therefore checks |g| <= 1
171	 *    (not < 1): the clamp value 1.0 is a legitimate, deterministic
172	 *    kernel output, and clamped-to-1.0 is still byte-comparable (same
173	 *    clamp fires on replay). The float kernel clamps at a different
174	 *    threshold — 8.664339742f (sleefsimdsp.c), not the double 18.714973875
175	 *    (the two thresholds are per-element-type constants) — but the same
176	 *    |g| <= 1 sentinel conclusion holds for both: inputs above the float
177	 *    threshold still clamp to exactly +-1.0f by design.
178	 *  - pow : base 1+u*9 in [1, 10-2^-49] (u*9 scaling, +1 keeps it >= 1:
179	 *    avoids 0^0, 0^negative and negative-base branch complexity
180	 *    entirely — every base is a positive normal number). Exponent
181	 *    u*8-4 in [-4, 4-2^-50]. Extreme products: pow(10, 4) = 1e4 (not
182	 *    reached, top exponent < 4) and pow(1, -4) = 1 — the result range is
183	 *    (0, 1e4] in both widths; float powf(10,4) = 1e4f exactly
184	 *    representable. No subnormal/overflow corners.
185	 * Every golden value is additionally checked for finiteness in init: a
186	 * NaN/Inf would make the byte-exact comparison meaningless (NaN != NaN). */
187	
188	static int sleef_neon_init(struct test *test)
189	{
190	    auto d = new(sleef_test_data);
191	    test->data = d;
192	    /* footprint knob, mdim precedent: read once, fail loudly on bad
193	     * values — a silent clamp would run a different campaign than the
194	     * operator asked for, and a non-multiple-of-4 would overrun the
195	     * float32x4 stride-4 vector loops (last iteration past the buffer) */
196	    int64_t knob = get_testspecific_knob_value_int(test, "nelems", ELEMS_DEFAULT);
197	    if (knob < ELEMS_MIN || knob > ELEMS_MAX) {
198	        report_fail_msg("nelems knob out of range: %ld (valid %d..%d, default %d)",
199	                        (long)knob, ELEMS_MIN, ELEMS_MAX, ELEMS_DEFAULT);
200	    }
201	    if (knob % 4 != 0) {
202	        report_fail_msg("nelems knob must be a multiple of 4 (float32x4_t stride): %ld",
203	                        (long)knob);
204	    }
205	    d->nelems = (int)knob;
206	    d->xd_trig = (double *)malloc(d->nelems * sizeof(double));
207	    d->xd_exp  = (double *)malloc(d->nelems * sizeof(double));
208	    d->xd_log  = (double *)malloc(d->nelems * sizeof(double));
209	    d->xf_trig = (float  *)malloc(d->nelems * sizeof(float));
210	    d->xf_exp  = (float  *)malloc(d->nelems * sizeof(float));
211	    d->xf_log  = (float  *)malloc(d->nelems * sizeof(float));
