213	    d->gd_cos = (double *)malloc(d->nelems * sizeof(double));
214	    d->gd_exp = (double *)malloc(d->nelems * sizeof(double));
215	    d->gd_log = (double *)malloc(d->nelems * sizeof(double));
216	    d->gf_sin = (float  *)malloc(d->nelems * sizeof(float));
217	    d->gf_cos = (float  *)malloc(d->nelems * sizeof(float));
218	    d->gf_exp = (float  *)malloc(d->nelems * sizeof(float));
219	    d->gf_log = (float  *)malloc(d->nelems * sizeof(float));
220	    /* u35 tier golden outputs */
221	    d->gd_sin35 = (double *)malloc(d->nelems * sizeof(double));
222	    d->gd_cos35 = (double *)malloc(d->nelems * sizeof(double));
223	    d->gd_log35 = (double *)malloc(d->nelems * sizeof(double));
224	    d->gd_exp2_35 = (double *)malloc(d->nelems * sizeof(double));
225	    d->gf_sin35 = (float  *)malloc(d->nelems * sizeof(float));
226	    d->gf_cos35 = (float  *)malloc(d->nelems * sizeof(float));
227	    d->gf_log35 = (float  *)malloc(d->nelems * sizeof(float));
228	    d->gf_exp2_35 = (float  *)malloc(d->nelems * sizeof(float));
229	    /* new families: inputs */
230	    d->xd_inv  = (double *)malloc(d->nelems * sizeof(double));
231	    d->xd_cbrt = (double *)malloc(d->nelems * sizeof(double));
232	    d->xd_pow2 = (double *)malloc(d->nelems * sizeof(double));
233	    d->xd_pexp = (double *)malloc(d->nelems * sizeof(double));
234	    d->xf_inv  = (float  *)malloc(d->nelems * sizeof(float));
235	    d->xf_cbrt = (float  *)malloc(d->nelems * sizeof(float));
236	    d->xf_pow2 = (float  *)malloc(d->nelems * sizeof(float));
237	    d->xf_pexp = (float  *)malloc(d->nelems * sizeof(float));
238	    /* new families: golden outputs */
239	    d->gd_asin = (double *)malloc(d->nelems * sizeof(double));
240	    d->gd_atan = (double *)malloc(d->nelems * sizeof(double));
241	    d->gd_cbrt = (double *)malloc(d->nelems * sizeof(double));
242	    d->gd_log10 = (double *)malloc(d->nelems * sizeof(double));
243	    d->gd_sinh = (double *)malloc(d->nelems * sizeof(double));
244	    d->gd_tanh = (double *)malloc(d->nelems * sizeof(double));
245	    d->gd_pow = (double *)malloc(d->nelems * sizeof(double));
246	    d->gf_asin = (float  *)malloc(d->nelems * sizeof(float));
247	    d->gf_atan = (float  *)malloc(d->nelems * sizeof(float));
248	    d->gf_cbrt = (float  *)malloc(d->nelems * sizeof(float));
249	    d->gf_log10 = (float  *)malloc(d->nelems * sizeof(float));
250	    d->gf_sinh = (float  *)malloc(d->nelems * sizeof(float));
251	    d->gf_tanh = (float  *)malloc(d->nelems * sizeof(float));
252	    d->gf_pow = (float  *)malloc(d->nelems * sizeof(float));
253	    if (!d->xd_trig || !d->xd_exp || !d->xd_log ||
254	        !d->xf_trig || !d->xf_exp || !d->xf_log ||
255	        !d->gd_sin || !d->gd_cos || !d->gd_exp || !d->gd_log ||
256	        !d->gf_sin || !d->gf_cos || !d->gf_exp || !d->gf_log ||
257	        !d->gd_sin35 || !d->gd_cos35 || !d->gd_log35 || !d->gd_exp2_35 ||
258	        !d->gf_sin35 || !d->gf_cos35 || !d->gf_log35 || !d->gf_exp2_35 ||
259	        !d->xd_inv || !d->xd_cbrt || !d->xd_pow2 || !d->xd_pexp ||
260	        !d->xf_inv || !d->xf_cbrt || !d->xf_pow2 || !d->xf_pexp ||
261	        !d->gd_asin || !d->gd_atan || !d->gd_cbrt || !d->gd_log10 ||
262	        !d->gd_sinh || !d->gd_tanh || !d->gd_pow ||
263	        !d->gf_asin || !d->gf_atan || !d->gf_cbrt || !d->gf_log10 ||
264	        !d->gf_sinh || !d->gf_tanh || !d->gf_pow) {
