266	    }
267	
268	    /* double inputs, per domain */
269	    for (int i = 0; i < d->nelems; ++i) {
270	        double u = uniform01();
271	        d->xd_trig[i] = (u * 2.0 - 1.0) * 3.141592653589793;   /* [-pi, pi] */
272	    }
273	    for (int i = 0; i < d->nelems; ++i) {
274	        double u = uniform01();
275	        d->xd_exp[i] = (u * 2.0 - 1.0) * 20.0;                 /* [-20, 20) */
276	    }
277	    for (int i = 0; i < d->nelems; ++i) {
278	        double u = uniform01();
279	        d->xd_log[i] = (u + 1.0e-300) * 1.0e10;                /* positive */
280	    }
281	
282	    /* float inputs, per domain. CAUTION: the [0,1) double does NOT stay
283	     * below 1 after narrowing — doubles in (1-2^-25, 1) round UP to exactly
284	     * 1.0f — so xf_trig/xf_exp can reach exactly +-pi_f / +-20_f (the domain
285	     * edge). Harmless: the u10 kernels carry their accuracy guarantee over
286	     * the whole input domain, determinism never depends on accuracy (the
287	     * golden values come from the very same kernel), and the init finiteness
288	     * tripwire below backstops the rest. */
289	    for (int i = 0; i < d->nelems; ++i) {
290	        float u = (float)uniform01();
291	        d->xf_trig[i] = (u * 2.0f - 1.0f) * 3.14159265f;       /* [-pi, pi] */
292	    }
293	    for (int i = 0; i < d->nelems; ++i) {
294	        float u = (float)uniform01();
295	        d->xf_exp[i] = (u * 2.0f - 1.0f) * 20.0f;              /* [-20, 20) */
296	    }
297	    for (int i = 0; i < d->nelems; ++i) {
298	        float u = (float)uniform01();
299	        d->xf_log[i] = (u + 1.0e-30f) * 1.0e10f;               /* positive */
300	    }
301	
302	    /* new-family inputs, double. log10 shares xd_log (positive mapping),
303	     * sinh/tanh share xd_exp ([-20,20) — see the boundary analysis above
304	     * for why the tanh clamp at |x|>18.715 makes |tanh| <= 1 inclusive). */
305	    for (int i = 0; i < d->nelems; ++i) {
306	        double u = uniform01();
307	        d->xd_inv[i] = u * 2.0 - 1.0;                          /* [-1, 1) */
308	    }
309	    for (int i = 0; i < d->nelems; ++i) {
310	        double u = uniform01();
311	        d->xd_cbrt[i] = u * 2000.0 - 1000.0;                   /* [-1000, 1000) */
312	    }
313	    for (int i = 0; i < d->nelems; ++i) {
314	        double u = uniform01();
315	        d->xd_pow2[i] = 1.0 + u * 9.0;                         /* [1, 10) base */
316	    }
317	    for (int i = 0; i < d->nelems; ++i) {
318	        double u = uniform01();
319	        d->xd_pexp[i] = u * 8.0 - 4.0;                         /* [-4, 4) exponent */
320	    }
321	
322	    /* new-family inputs, float (same narrowing caveat as xf_trig/xf_exp
323	     * above: e.g. 1+u*9 can round up to exactly 10.0f and the asin input
324	     * can reach exactly +-1.0f — both still inside/at the documented
325	     * domain edge, and determinism never depends on accuracy) */
326	    for (int i = 0; i < d->nelems; ++i) {
327	        float u = (float)uniform01();
328	        d->xf_inv[i] = u * 2.0f - 1.0f;                        /* [-1, 1) */
329	    }
330	    for (int i = 0; i < d->nelems; ++i) {
331	        float u = (float)uniform01();
332	        d->xf_cbrt[i] = u * 2000.0f - 1000.0f;                 /* [-1000, 1000) */
333	    }
334	    for (int i = 0; i < d->nelems; ++i) {
335	        float u = (float)uniform01();
336	        d->xf_pow2[i] = 1.0f + u * 9.0f;                       /* [1, 10) base */
337	    }
338	    for (int i = 0; i < d->nelems; ++i) {
339	        float u = (float)uniform01();
340	        d->xf_pexp[i] = u * 8.0f - 4.0f;                       /* [-4, 4) exponent */
341	    }
342	
343	    /* golden outputs from the very same kernels, once; any non-finite
344	     * result would poison the byte-exact comparison (NaN != NaN), so fail
345	     * loudly at the source instead (same tripwire as openblas_dgemm) */
346	    for (int i = 0; i < d->nelems; i += 2) {
347	        float64x2_t x = vld1q_f64(&d->xd_trig[i]);
348	        vst1q_f64(&d->gd_sin[i], Sleef_sind2_u10advsimd(x));
349	        vst1q_f64(&d->gd_cos[i], Sleef_cosd2_u10advsimd(x));
350	        x = vld1q_f64(&d->xd_exp[i]);
351	        vst1q_f64(&d->gd_exp[i], Sleef_expd2_u10advsimd(x));
352	        x = vld1q_f64(&d->xd_log[i]);
353	        vst1q_f64(&d->gd_log[i], Sleef_logd2_u10advsimd(x));
354	        /* u35 second tier: same inputs, the OTHER polynomial implementation */
355	        vst1q_f64(&d->gd_sin35[i], Sleef_sind2_u35advsimd(vld1q_f64(&d->xd_trig[i])));
356	        vst1q_f64(&d->gd_cos35[i], Sleef_cosd2_u35advsimd(vld1q_f64(&d->xd_trig[i])));
357	        vst1q_f64(&d->gd_log35[i], Sleef_logd2_u35advsimd(vld1q_f64(&d->xd_log[i])));
358	        /* u35 has NO exp — exp2 is the independent-chain stand-in */
359	        vst1q_f64(&d->gd_exp2_35[i], Sleef_exp2d2_u35advsimd(vld1q_f64(&d->xd_exp[i])));
360	        /* new families: asin/atan ([-1,1) inputs), cbrt ([-1000,1000)),
361	         * log10 (positive log inputs), sinh/tanh ([-20,20) exp inputs),
362	         * pow (base [1,10) x exponent [-4,4), the only 2-arg kernel) */
363	        vst1q_f64(&d->gd_asin[i], Sleef_asind2_u35advsimd(vld1q_f64(&d->xd_inv[i])));
364	        vst1q_f64(&d->gd_atan[i], Sleef_atand2_u35advsimd(vld1q_f64(&d->xd_inv[i])));
365	        vst1q_f64(&d->gd_cbrt[i], Sleef_cbrtd2_u35advsimd(vld1q_f64(&d->xd_cbrt[i])));
366	        vst1q_f64(&d->gd_log10[i], Sleef_log10d2_u10advsimd(vld1q_f64(&d->xd_log[i])));
367	        vst1q_f64(&d->gd_sinh[i], Sleef_sinhd2_u35advsimd(vld1q_f64(&d->xd_exp[i])));
368	        vst1q_f64(&d->gd_tanh[i], Sleef_tanhd2_u35advsimd(vld1q_f64(&d->xd_exp[i])));
369	        vst1q_f64(&d->gd_pow[i], Sleef_powd2_u10advsimd(vld1q_f64(&d->xd_pow2[i]),
370	                                                        vld1q_f64(&d->xd_pexp[i])));
371	    }
372	    for (int i = 0; i < d->nelems; i += 4) {
373	        float32x4_t x = vld1q_f32(&d->xf_trig[i]);
374	        vst1q_f32(&d->gf_sin[i], Sleef_sinf4_u10advsimd(x));
375	        vst1q_f32(&d->gf_cos[i], Sleef_cosf4_u10advsimd(x));
376	        x = vld1q_f32(&d->xf_exp[i]);
377	        vst1q_f32(&d->gf_exp[i], Sleef_expf4_u10advsimd(x));
378	        x = vld1q_f32(&d->xf_log[i]);
379	        vst1q_f32(&d->gf_log[i], Sleef_logf4_u10advsimd(x));
380	        /* u35 second tier */
381	        vst1q_f32(&d->gf_sin35[i], Sleef_sinf4_u35advsimd(vld1q_f32(&d->xf_trig[i])));
382	        vst1q_f32(&d->gf_cos35[i], Sleef_cosf4_u35advsimd(vld1q_f32(&d->xf_trig[i])));
383	        vst1q_f32(&d->gf_log35[i], Sleef_logf4_u35advsimd(vld1q_f32(&d->xf_log[i])));
384	        vst1q_f32(&d->gf_exp2_35[i], Sleef_exp2f4_u35advsimd(vld1q_f32(&d->xf_exp[i])));
385	        /* new families (asin/atan/cbrt/sinh/tanh at u35, log10/pow at u10) */
386	        vst1q_f32(&d->gf_asin[i], Sleef_asinf4_u35advsimd(vld1q_f32(&d->xf_inv[i])));
387	        vst1q_f32(&d->gf_atan[i], Sleef_atanf4_u35advsimd(vld1q_f32(&d->xf_inv[i])));
388	        vst1q_f32(&d->gf_cbrt[i], Sleef_cbrtf4_u35advsimd(vld1q_f32(&d->xf_cbrt[i])));
389	        vst1q_f32(&d->gf_log10[i], Sleef_log10f4_u10advsimd(vld1q_f32(&d->xf_log[i])));
390	        vst1q_f32(&d->gf_sinh[i], Sleef_sinhf4_u35advsimd(vld1q_f32(&d->xf_exp[i])));
391	        vst1q_f32(&d->gf_tanh[i], Sleef_tanhf4_u35advsimd(vld1q_f32(&d->xf_exp[i])));
392	        vst1q_f32(&d->gf_pow[i], Sleef_powf4_u10advsimd(vld1q_f32(&d->xf_pow2[i]),
393	                                                        vld1q_f32(&d->xf_pexp[i])));
394	    }
395	    for (int i = 0; i < d->nelems; ++i) {
396	        double gs = d->gd_sin[i], gc = d->gd_cos[i];
397	        double ge = d->gd_exp[i], gl = d->gd_log[i];
398	        if (gs != gs || gs > 1.0 || gs < -1.0 || gc != gc || gc > 1.0 || gc < -1.0 ||
399	            ge != ge || ge > 1.0e300 || ge < 0.0 ||
400	            gl != gl || gl > 1.0e300 || gl < -1.0e300) {
401	            report_fail_msg("double golden value not finite/in-range at element %d "
402	                            "(domain mapping needs tighter scaling)", i);
403	        }
404	    }
405	    for (int i = 0; i < d->nelems; ++i) {
406	        float gs = d->gf_sin[i], gc = d->gf_cos[i];
407	        float ge = d->gf_exp[i], gl = d->gf_log[i];
408	        if (gs != gs || gs > 1.0f || gs < -1.0f || gc != gc || gc > 1.0f || gc < -1.0f ||
409	            ge != ge || ge > 1.0e30f || ge < 0.0f ||
410	            gl != gl || gl > 1.0e30f || gl < -1.0e30f) {
411	            report_fail_msg("float golden value not finite/in-range at element %d "
412	                            "(domain mapping needs tighter scaling)", i);
413	        }
414	    }
415	    /* finiteness sentinels, u35 tier. exp2(20) ~ 1.05e6 so the bound is
416	     * 1e7 (an order of headroom); sin/cos stay in [-1,1]; log shares the
417	     * original log range. */
418	    for (int i = 0; i < d->nelems; ++i) {
419	        double gs = d->gd_sin35[i], gc = d->gd_cos35[i];
420	        double gl = d->gd_log35[i], ge = d->gd_exp2_35[i];
421	        if (gs != gs || gs > 1.0 || gs < -1.0 || gc != gc || gc > 1.0 || gc < -1.0 ||
422	            gl != gl || gl > 1.0e300 || gl < -1.0e300 ||
423	            ge != ge || ge > 1.0e7 || ge < 0.0) {
424	            report_fail_msg("double u35 golden value not finite/in-range at element %d "
425	                            "(domain mapping needs tighter scaling)", i);
426	        }
427	    }
428	    for (int i = 0; i < d->nelems; ++i) {
429	        float gs = d->gf_sin35[i], gc = d->gf_cos35[i];
430	        float gl = d->gf_log35[i], ge = d->gf_exp2_35[i];
431	        if (gs != gs || gs > 1.0f || gs < -1.0f || gc != gc || gc > 1.0f || gc < -1.0f ||
432	            gl != gl || gl > 1.0e30f || gl < -1.0e30f ||
433	            ge != ge || ge > 1.0e7f || ge < 0.0f) {
434	            report_fail_msg("float u35 golden value not finite/in-range at element %d "
435	                            "(domain mapping needs tighter scaling)", i);
436	        }
437	    }
438	    /* finiteness sentinels, new families:
439	     *  - asin/atan: |g| <= 1.6 (pi/2 ~ 1.5708 plus headroom; atan can only
440	     *    approach pi/2 but the shared bound keeps it simple)
441	     *  - cbrt: |g| < 10 (cbrt(1000)=10, not included), sentinel 1.0e3
442	     *  - log10: (-700, 25] double / (-30, 25] float (domain is
443	     *    (-290, 10] / (-20, 10], generous headroom)
444	     *  - sinh: |g| < 1e9 (sinh(20) ~ 2.42e8)
445	     *  - tanh: |g| <= 1 INCLUSIVE — SLEEF clamps to exactly 1.0 for
446	     *    |x| > 18.714973875 (see boundary analysis; deterministic)
447	     *  - pow: g in (0, 1e4] (pow(10,4)=1e4 is the theoretical max, not
448	     *    reached; strictly positive since base >= 1 > 0) */
449	    for (int i = 0; i < d->nelems; ++i) {
450	        double ga = d->gd_asin[i], gt = d->gd_atan[i], gc = d->gd_cbrt[i];
451	        double gl10 = d->gd_log10[i], gsh = d->gd_sinh[i], gth = d->gd_tanh[i], gp = d->gd_pow[i];
452	        if (ga != ga || ga > 1.6 || ga < -1.6 ||
453	            gt != gt || gt > 1.6 || gt < -1.6 ||
454	            gc != gc || gc > 1.0e3 || gc < -1.0e3 ||
455	            gl10 != gl10 || gl10 > 25.0 || gl10 < -700.0 ||
456	            gsh != gsh || gsh > 1.0e9 || gsh < -1.0e9 ||
457	            gth != gth || gth > 1.0 || gth < -1.0 ||
458	            gp != gp || gp > 1.0e4 || gp <= 0.0) {
459	            report_fail_msg("double new-family golden value not finite/in-range at element %d "
460	                            "(domain mapping needs tighter scaling)", i);
461	        }
462	    }
463	    for (int i = 0; i < d->nelems; ++i) {
464	        float ga = d->gf_asin[i], gt = d->gf_atan[i], gc = d->gf_cbrt[i];
465	        float gl10 = d->gf_log10[i], gsh = d->gf_sinh[i], gth = d->gf_tanh[i], gp = d->gf_pow[i];
466	        if (ga != ga || ga > 1.6f || ga < -1.6f ||
467	            gt != gt || gt > 1.6f || gt < -1.6f ||
468	            gc != gc || gc > 1.0e3f || gc < -1.0e3f ||
469	            gl10 != gl10 || gl10 > 25.0f || gl10 < -30.0f ||
470	            gsh != gsh || gsh > 1.0e9f || gsh < -1.0e9f ||
471	            gth != gth || gth > 1.0f || gth < -1.0f ||
472	            gp != gp || gp > 1.0e4f || gp <= 0.0f) {
473	            report_fail_msg("float new-family golden value not finite/in-range at element %d "
474	                            "(domain mapping needs tighter scaling)", i);
475	        }
476	    }
477	    return EXIT_SUCCESS;
478	}
