682	static int sleef_neon_cleanup(struct test *test)
683	{
684	    auto d = CAST(test->data);
685	    free(d->xd_trig); free(d->xd_exp); free(d->xd_log);
686	    free(d->xf_trig); free(d->xf_exp); free(d->xf_log);
687	    free(d->gd_sin); free(d->gd_cos); free(d->gd_exp); free(d->gd_log);
688	    free(d->gf_sin); free(d->gf_cos); free(d->gf_exp); free(d->gf_log);
689	    free(d->gd_sin35); free(d->gd_cos35); free(d->gd_log35); free(d->gd_exp2_35);
690	    free(d->gf_sin35); free(d->gf_cos35); free(d->gf_log35); free(d->gf_exp2_35);
691	    free(d->xd_inv); free(d->xd_cbrt); free(d->xd_pow2); free(d->xd_pexp);
692	    free(d->xf_inv); free(d->xf_cbrt); free(d->xf_pow2); free(d->xf_pexp);
693	    free(d->gd_asin); free(d->gd_atan); free(d->gd_cbrt); free(d->gd_log10);
694	    free(d->gd_sinh); free(d->gd_tanh); free(d->gd_pow);
695	    free(d->gf_asin); free(d->gf_atan); free(d->gf_cbrt); free(d->gf_log10);
696	    free(d->gf_sinh); free(d->gf_tanh); free(d->gf_pow);
697	    delete d;
698	    return EXIT_SUCCESS;
699	}
700	
701	DECLARE_TEST(sleef_neon, "SLEEF vectorized transcendentals (NEON polynomial FMA chains, sin/cos/exp/log + u35 tier (exp2) + asin/atan/cbrt/log10/sinh/tanh/pow, double+float; footprint knob -O sleef_neon.nelems=N, 128..262144, default 1024)")
702	  .groups = DECLARE_TEST_GROUPS(&group_math),
703	  .test_init = sleef_neon_init,
704	  .test_run = sleef_neon_run,
705	  .test_cleanup = sleef_neon_cleanup,
706	  .fracture_loop_count = 4,
707	  .quality_level = TEST_QUALITY_PROD,
708	END_DECLARE_TEST
