};
static Data *g_data;
static void *init_thread(void *) {
    g_data = new Data;
    g_data->gemm = nullptr;
    arm_compute::NEScheduler::get().set_num_threads(1);
    arm_compute::TensorInfo info(arm_compute::TensorShape(DIM, DIM), 1, arm_compute::DataType::F32);
